const pvmc1AllowedMachineEdgeKeys = new Set<string>(pvmc1MachineEdgeAuthorities.map((row) =>
  row.coordinate.machineId + "\u0000" + row.coordinate.from + "\u0000" + row.coordinate.to));

export function isAllowedPvmc1MachineEdge(machineId: string, from: string, to: string): boolean {
  return pvmc1AllowedMachineEdgeKeys.has(machineId + "\u0000" + from + "\u0000" + to);
}

export const pvmc1MachineTransitionSqlRowCount = 151 as const;
export const pvmc1MachineTransitionSqlSha256 = "4caa5d71547050f8f7fc32448b32cc088ed59f165ced3bdce776bf63817c237c" as const;
export const pvmc1MachineTransitionSqlUtf8Base64 = "" as const;

export function pvmc1MachineTransitionSqlBytes(): Uint8Array {
  const bytes = Uint8Array.from(Buffer.from(pvmc1MachineTransitionSqlUtf8Base64, 'base64'));
  const digest = createHash('sha256').update(bytes).digest('hex');
  if (digest !== pvmc1MachineTransitionSqlSha256) throw new TypeError('PVMC1 machine SQL digest mismatch');
  return bytes;
}

